    '<select onchange="rl2SetPeriodCount(this.value)" style="background:#1a1d27;border:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,.75);border-radius:7px;padding:6px 10px;font-size:12px;font-family:\'DM Sans\',sans-serif;cursor:pointer;">'+opts+'</select></div>'+
    '<div style="display:flex;align-items:center;gap:8px;"><span style="font-size:11px;color:rgba(255,255,255,.35);font-family:\'DM Mono\',monospace;text-transform:uppercase;letter-spacing:.08em;">Client</span>'+
    '<select onchange="rl2SetClientFilter(this.value)" style="background:#1a1d27;border:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,.75);border-radius:7px;padding:6px 10px;font-size:12px;font-family:\'DM Sans\',sans-serif;cursor:pointer;">'+clientOpts+'</select></div>'+
    '</div>';
