function rl2BuildComparisonGrid(snaps){
  var cf=rl2ClientFilter;
  var cols=snaps.length;
  var metrics=snaps.map(function(s){return rl2SnapMetrics(s,cf);});
  var first=metrics[0],last=metrics[metrics.length-1];
  var avgDelta=last.avg-first.avg;
  var colW='repeat('+cols+',1fr)';
  var headerStyle='font-size:10px;color:rgba(255,255,255,.35);font-family:\'DM Mono\',monospace;text-transform:uppercase;letter-spacing:.09em;';
  var cellStyle='font-size:13px;font-weight:700;font-family:\'DM Mono\',monospace;color:rgba(255,255,255,.85);text-align:center;';
  // Header row
  var headerRow='<div style="grid-column:1;'+headerStyle+'padding:12px 16px;">Metric</div>'+
    snaps.map(function(s,i){
      return '<div style="'+headerStyle+'padding:12px 8px;text-align:center;'+(i===snaps.length-1?'color:rgba(201,162,39,.8);':'')+
        '">'+rl2FmtDate(s.capturedAt)+'<div style="font-size:9px;opacity:.6;margin-top:1px;">'+(s.label||'').slice(0,18)+'</div></div>';
    }).join('')+
    '<div style="'+headerStyle+'padding:12px 8px;text-align:center;">Change</div>';
  // Row builder
  function mkRow(label,vals,deltaVal,fmtFn,colorFn,isLast){
    var base='border-bottom:'+(isLast?'none':'1px solid rgba(255,255,255,.04)')+';';
    return '<div style="'+base+'grid-column:1;font-size:12px;color:rgba(255,255,255,.55);padding:11px 16px;font-family:\'DM Sans\',sans-serif;">'+label+'</div>'+
      vals.map(function(v,i){
        var col=colorFn?colorFn(v):'rgba(255,255,255,.85)';
        var isLatest=i===vals.length-1;
        return '<div style="'+base+'text-align:center;padding:11px 8px;font-size:13px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+col+';'+(isLatest?'background:rgba(201,162,39,.04);':'')+'">'+fmtFn(v)+'</div>';
      }).join('')+
      (deltaVal!==null?'<div style="'+base+'text-align:center;padding:11px 8px;font-size:12px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+(deltaVal>0?'#22c55e':deltaVal<0?'#ef4444':'rgba(255,255,255,.3)')+';background:rgba(255,255,255,.02);">'+
        (deltaVal>0?'↑ +'+deltaVal+(typeof deltaVal==='number'&&label.includes('%')?'':''): deltaVal<0?'↓ '+deltaVal:'→ 0')+'</div>':'<div style="'+base+'"></div>');
  }
  var rows=[
    mkRow('Avg Progress (%)',metrics.map(function(m){return m.avg;}),avgDelta,
      function(v){return v+'%';},
      function(v){return v>=70?'#22c55e':v>=40?'#eab308':'#ef4444';},false),
    mkRow('Total Projects',metrics.map(function(m){return m.total;}),last.total-first.total,
      function(v){return v;},null,false),
    mkRow('Active',metrics.map(function(m){return m.active;}),last.active-first.active,
      function(v){return v;},
      function(v){return v>0?'#60a5fa':'rgba(255,255,255,.4)';},false),
    mkRow('Completed',metrics.map(function(m){return m.done;}),last.done-first.done,
      function(v){return v;},
      function(v){return v>0?'#22c55e':'rgba(255,255,255,.4)';},false),
    mkRow('Blocked',metrics.map(function(m){return m.blocked;}),last.blocked-first.blocked,
      function(v){return v;},
      function(v){return v>0?'#ef4444':'rgba(255,255,255,.4)';},false),
    mkRow('To Do',metrics.map(function(m){return m.todo;}),last.todo-first.todo,
      function(v){return v;},null,true),
  ].join('');
  return '<div style="background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.08);border-radius:12px;overflow:hidden;margin-bottom:28px;">'+
    '<div style="display:grid;grid-template-columns:180px '+colW+' 90px;background:rgba(255,255,255,.03);border-bottom:1px solid rgba(255,255,255,.07);">'+headerRow+'</div>'+
    '<div style="display:grid;grid-template-columns:180px '+colW+' 90px;">'+rows+'</div>'+
    '</div>';
}
function rl2BuildTrendLine(allSnaps,filtered){
  if(!filtered||filtered.length<2)return'';
  var cf=rl2ClientFilter;
  var W=800,H=220,PAD_L=42,PAD_R=20,PAD_T=16,PAD_B=48;
  var chartW=W-PAD_L-PAD_R,chartH=H-PAD_T-PAD_B;
  var pts=filtered.map(function(s){return rl2SnapMetrics(s,cf).avg;});
  var maxV=Math.max(100,Math.max.apply(null,pts)),minV=0;
  var range=maxV-minV||1;
  var xs=pts.map(function(_,i){return PAD_L+i/(pts.length-1)*chartW;});
  var ys=pts.map(function(v){return PAD_T+chartH*(1-(v-minV)/range);});
  var gridLines=[0,25,50,75,100].map(function(v){
    var y=PAD_T+chartH*(1-v/100);
    return '<line x1="'+PAD_L+'" y1="'+y.toFixed(1)+'" x2="'+(W-PAD_R)+'" y2="'+y.toFixed(1)+'" stroke="rgba(255,255,255,.06)" stroke-width="1"/>'+
      '<text x="'+(PAD_L-6)+'" y="'+(y+4).toFixed(1)+'" text-anchor="end" font-size="10" fill="rgba(255,255,255,.25)" font-family="DM Mono,monospace">'+v+'</text>';
  }).join('');
  var area='M '+xs[0]+' '+(PAD_T+chartH)+' L '+xs[0]+' '+ys[0]+' '+xs.map(function(x,i){return'L '+x.toFixed(1)+' '+ys[i].toFixed(1);}).join(' ')+' L '+xs[xs.length-1]+' '+(PAD_T+chartH)+' Z';
  var line='M '+xs[0]+' '+ys[0]+' '+xs.map(function(x,i){return'L '+x.toFixed(1)+' '+ys[i].toFixed(1);}).join(' ');
  var dots=xs.map(function(x,i){
    var y=ys[i];var v=pts[i];var snap=filtered[i];
    return '<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="5" fill="#c9a227" stroke="#0b0b12" stroke-width="2"/>'+
      '<text x="'+x.toFixed(1)+'" y="'+(y-12).toFixed(1)+'" text-anchor="middle" font-size="11" font-weight="700" fill="#c9a227" font-family="DM Mono,monospace">'+v+'%</text>';
  }).join('');
  var labels=xs.map(function(x,i){
    return '<text x="'+x.toFixed(1)+'" y="'+(PAD_T+chartH+22).toFixed(1)+'" text-anchor="middle" font-size="10" fill="rgba(255,255,255,.35)" font-family="DM Sans,sans-serif">'+rl2FmtDate(filtered[i].capturedAt)+'</text>';
  }).join('');
  var svgDefs='<defs><linearGradient id="rlGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c9a227" stop-opacity="0.25"/><stop offset="100%" stop-color="#c9a227" stop-opacity="0.02"/></linearGradient></defs>';
  var svg=svgDefs+gridLines+'<path d="'+area+'" fill="url(#rlGrad)"/><path d="'+line+'" fill="none" stroke="#c9a227" stroke-width="2.5" stroke-linejoin="round"/>'+dots+labels;
  return '<div style="background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:20px 24px;margin-bottom:28px;">'+
    '<div style="font-size:9px;color:rgba(255,255,255,.3);font-family:\'DM Mono\',monospace;letter-spacing:.12em;text-transform:uppercase;margin-bottom:16px;">Progress Trend — Avg Completion %</div>'+
    '<div style="overflow-x:auto;"><svg viewBox="0 0 '+W+' '+H+'" width="100%" style="display:block;min-width:400px;" xmlns="http://www.w3.org/2000/svg">'+svg+'</svg></div>'+
    '</div>';
}
function rl2BuildProjectMatrix(snaps){
  if(!snaps.length)return'';
  var cf=rl2ClientFilter;
  var cols=snaps.length;
  var colW='repeat('+cols+',90px)';
  // Collect all unique projects across snaps
  var projMap={};
  snaps.forEach(function(s,si){
    (s.projects||[]).forEach(function(p){
      var key=String(p.id);
      if(!projMap[key])projMap[key]={id:p.id,name:p.name,customer:p.customer||'',snapPct:{}};
      projMap[key].snapPct[si]=p.completionPct||0;
    });
  });
  var projects=Object.values(projMap);
  if(cf)projects=projects.filter(function(p){return p.customer===cf;});
  if(!projects.length)return'';
  // Sort by latest snapshot pct desc, then name
  projects.sort(function(a,b){
    var la=a.snapPct[cols-1]!==undefined?a.snapPct[cols-1]:a.snapPct[Object.keys(a.snapPct).pop()]||0;
    var lb=b.snapPct[cols-1]!==undefined?b.snapPct[cols-1]:b.snapPct[Object.keys(b.snapPct).pop()]||0;
    return lb-la||a.name.localeCompare(b.name);
  });
  var hdrStyle='font-size:10px;color:rgba(255,255,255,.3);font-family:\'DM Mono\',monospace;text-transform:uppercase;letter-spacing:.08em;padding:10px 8px;text-align:center;';
  var snapHeaders=snaps.map(function(s,i){
    return '<div style="'+hdrStyle+(i===snaps.length-1?'color:rgba(201,162,39,.7);':'')+
      '">'+rl2FmtDate(s.capturedAt)+'</div>';
  }).join('');
  var rows=projects.map(function(p){
    var first=p.snapPct[0];
    var last=p.snapPct[cols-1]!==undefined?p.snapPct[cols-1]:null;
    var delta=(first!==undefined&&last!==null)?last-first:null;
    var cells=snaps.map(function(s,i){
      var v=p.snapPct[i];
      if(v===undefined)return'<div style="text-align:center;padding:9px 8px;font-size:12px;color:rgba(255,255,255,.18);font-family:\'DM Mono\',monospace;">—</div>';
      var col=v>=70?'#22c55e':v>=40?'#eab308':'#ef4444';
      var isLatest=i===snaps.length-1;
      return '<div style="text-align:center;padding:9px 8px;font-size:12px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+col+';'+(isLatest?'background:rgba(201,162,39,.04);':'')+'">'+v+'%</div>';
    }).join('');
    var deltaCell=delta!==null?'<div style="text-align:center;padding:9px 8px;font-size:12px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+(delta>0?'#22c55e':delta<0?'#ef4444':'rgba(255,255,255,.3)')+';">'+(delta>0?'↑ +'+delta+'%':delta<0?'↓ '+delta+'%':'→')+'</div>':
      '<div style="text-align:center;padding:9px 8px;font-size:12px;color:rgba(255,255,255,.2);">—</div>';
    return '<div style="display:grid;grid-template-columns:1fr '+colW+' 80px;border-bottom:1px solid rgba(255,255,255,.04);align-items:center;">'+
      '<div style="padding:9px 16px;min-width:0;"><div style="font-size:12px;color:rgba(255,255,255,.82);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+p.name+'</div>'+
      (p.customer?'<div style="font-size:10px;color:rgba(255,255,255,.3);margin-top:1px;">'+p.customer+'</div>':'')+
      '</div>'+cells+deltaCell+'</div>';
  }).join('');
  return '<div style="background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.08);border-radius:12px;overflow:hidden;">'+
    '<div style="display:grid;grid-template-columns:1fr '+colW+' 80px;background:rgba(255,255,255,.03);border-bottom:1px solid rgba(255,255,255,.07);">'+
    '<div style="'+hdrStyle+'padding:10px 16px;text-align:left;">Project</div>'+snapHeaders+
    '<div style="'+hdrStyle+'">Change</div>'+
    '</div>'+
    '<div>'+rows+'</div>'+
    '</div>';
}
